'use strict';

// MODULES //

var limits = require( '@data-apis/limits' );
var fetchBounded = require( '@data-apis/http/fetch-bounded' );


// FUNCTIONS //

/**
* Sanitizes a response header for provenance.
*
* @private
* @param {string|null} value - header value
* @returns {string|undefined} sanitized value
*/
function safeHeader( value ) {
	if ( !value ) {
		return undefined;
	}
	return value.replace( /[\u0000-\u001f\u007f]/g, ' ' ).trim().slice( 0, 512 ) || undefined;
}


// MAIN //

/**
* Fetches a report from a stable HTTPS URL.
*
* @param {Object} context - source context
* @returns {Promise<Object>} payload bytes and origin
*/
async function fetchUrl( context ) {
	var result = await fetchBounded( context.source.url, {
		'fetchImpl': context.fetchImpl,
		'maxBytes': limits.maxHttpBytes,
		'maxRetries': context.maxRetries,
		'sleep': context.sleep
	} );
	var etag = safeHeader( result.response.headers.get( 'etag' ) );
	var lastModified = safeHeader( result.response.headers.get( 'last-modified' ) );
	var response = {};

	if ( etag ) {
		response.etag = etag;
	}
	if ( lastModified ) {
		response.last_modified = lastModified;
	}
	return {
		'bytes': result.bytes,
		'origin': Object.assign( {
			'type': 'url',
			'endpoint': context.source.url
		}, Object.keys( response ).length > 0 ? { 'response': response } : {} )
	};
}


// EXPORTS //

module.exports = fetchUrl;
